import numpy as np


class BanditDirMemoryPatternES:
    """
    Feasibility-rule mixed-integer ES with a bandit-scheduled incumbent intensifier.
    - Stratified initial sample; cached evaluations (repeats cost no budget).
    - (mu+lambda) ES with tournament parents and 1/5-rule step control.
    - Intensifier: integer single-move sweep, pairwise integer sweep (small
      cardinalities), then momentum pattern search seeded by a persistent
      successful direction and step scale shared across intensifications.
    - Restart operators (elite, config-best, incumbent, fresh) are chosen by a
      bandit that rewards operators whose runs improve the global best.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng(np.random.randint(0, 2 ** 31 - 1))
        dim = self.dim
        lb = np.asarray(func.bounds.lb, dtype=float).copy()
        ub = np.asarray(func.bounds.ub, dtype=float).copy()
        span = ub - lb
        vtypes = [str(t) for t in func.variable_types]
        n_values = getattr(func, "n_values", None)

        nv = np.ones(dim, dtype=int)
        is_int = np.zeros(dim, dtype=bool)
        for i, t in enumerate(vtypes):
            if t != "continuous":
                is_int[i] = True
                nv[i] = max(int(n_values[i]), 1)
        ints = np.where(is_int)[0]
        cont = np.where(~is_int)[0]
        is_ord = np.array([t == "ordinal" for t in vtypes], dtype=bool)

        self._evals = 0
        self._cache = {}
        self._pool = []
        self._best_key = (2, np.inf, 0.0)
        self._best_x = None
        self._best_f = np.inf
        self._done = False
        self._dir_mem = None      # persistent successful continuous direction
        self._scale_mem = 0.05    # persistent successful step scale
        POOL_MAX = 200

        def repair(x):
            y = np.clip(x, lb, ub)
            if ints.size:
                y[ints] = np.clip(np.rint(y[ints]), 0, nv[ints] - 1)
            return y

        def make_key(f, g):
            g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e9, posinf=1e9, neginf=0.0)
            v = float(np.sum(np.maximum(g, 0.0)))
            if np.isfinite(f) and v <= 0.0:
                return (0, float(f), 0.0)
            return (1, v if v > 0.0 else 1.0, 0.0)

        def evaluate(x):
            if self._done:
                return None
            x = repair(x)
            ck = tuple(np.round(x, 10).tolist())
            if ck in self._cache:
                return self._cache[ck]
            if self._evals >= self.budget:
                self._done = True
                return None
            f, g = func(x)
            self._evals += 1
            f = float(f)
            k = make_key(f, g)
            res = (k, x.copy())
            self._cache[ck] = res
            self._pool.append(res)
            if len(self._pool) > 2 * POOL_MAX:
                self._pool.sort(key=lambda t: t[0])
                self._pool = self._pool[:POOL_MAX]
            if k < self._best_key:
                self._best_key = k
                self._best_x = x.copy()
                self._best_f = f
            return res

        def random_point():
            y = rng.uniform(lb, ub)
            if ints.size:
                y[ints] = rng.integers(0, nv[ints])
            return y

        def lhs_sample(n):
            pts = np.empty((n, dim))
            for j in range(dim):
                if is_int[j]:
                    lv = np.arange(n) % nv[j]
                    pts[:, j] = rng.permutation(lv)
                else:
                    u = (rng.permutation(n) + rng.random(n)) / n
                    pts[:, j] = lb[j] + u * span[j]
            return pts

        def mutate(x, sig, pint):
            y = x.copy()
            if cont.size:
                pc = rng.uniform(1.0 / cont.size, 1.0)
                mask = rng.random(cont.size) < pc
                if rng.random() < 0.1:
                    step = np.clip(rng.standard_cauchy(cont.size), -5, 5) * 0.1
                else:
                    step = rng.normal(0.0, sig, cont.size)
                y[cont] += step * span[cont] * mask
            for i in ints:
                if rng.random() < pint:
                    if is_ord[i]:
                        if rng.random() < 0.8:
                            y[i] += rng.choice([-1.0, 1.0])
                        else:
                            y[i] += rng.choice([-1.0, 1.0]) * (1 + rng.geometric(0.4))
                    elif nv[i] > 1:
                        if nv[i] == 2:
                            y[i] = 1 - int(round(y[i]))
                        else:
                            new = int(rng.integers(nv[i] - 1))
                            if new >= int(round(y[i])):
                                new += 1
                            y[i] = new
            return repair(y)

        def tournament(pop):
            a = pop[int(rng.integers(len(pop)))]
            b = pop[int(rng.integers(len(pop)))]
            return a if a[0] <= b[0] else b

        def run_es(x0, sig, mu=5, lam=10, patience=22):
            r0 = evaluate(x0)
            if r0 is None:
                return
            pop = [r0]
            for _ in range(mu - 1):
                r = evaluate(mutate(x0, sig, 1.0 / dim))
                if r is None:
                    return
                pop.append(r)
            pop.sort(key=lambda t: t[0])
            stall = 0
            while not self._done:
                best_before = pop[0][0]
                succ = 0
                children = []
                for _ in range(lam):
                    parent = tournament(pop)
                    pint = rng.choice([1.0 / dim, 2.0 / dim, 0.3])
                    r = evaluate(mutate(parent[1], sig, pint))
                    if r is None:
                        return
                    children.append(r)
                    if r[0] < parent[0]:
                        succ += 1
                pop = sorted(pop + children, key=lambda t: t[0])[:mu]
                rate = succ / lam
                sig = sig * 1.22 if rate > 0.2 else sig * 0.82
                sig = min(max(sig, 1e-4), 0.5)
                if pop[0][0] < best_before:
                    stall = 0
                else:
                    stall += 1
                if stall >= patience:
                    return sig

        def int_sweep(cur):
            for i in ints:
                cur_val = int(round(cur[1][i]))
                for v in range(int(nv[i])):
                    if v == cur_val:
                        continue
                    if is_ord[i] and nv[i] > 6 and abs(v - cur_val) > 2:
                        continue
                    y = cur[1].copy()
                    y[i] = v
                    r = evaluate(y)
                    if r is None:
                        return cur, False
                    if r[0] < cur[0]:
                        return r, True
            return cur, False

        def pair_sweep(cur):
            if ints.size < 2:
                return cur, False
            for a in range(len(ints)):
                for b in range(a + 1, len(ints)):
                    i, j = ints[a], ints[b]
                    if nv[i] * nv[j] > 64:
                        continue
                    ci = int(round(cur[1][i]))
                    cj = int(round(cur[1][j]))
                    for vi in range(int(nv[i])):
                        for vj in range(int(nv[j])):
                            if vi == ci and vj == cj:
                                continue
                            y = cur[1].copy()
                            y[i] = vi
                            y[j] = vj
                            r = evaluate(y)
                            if r is None:
                                return cur, False
                            if r[0] < cur[0]:
                                return r, True
            return cur, False

        def pattern_search(cur, scale):
            """Momentum pattern search in the continuous subspace. The remembered
            successful direction is tried first; Hooke-Jeeves extrapolation follows
            each move; successful directions run out with doubling multipliers."""
            c = cont.size
            if not c:
                return cur, False
            moved = False
            prev_x = None
            while not self._done and scale > 1e-5:
                if prev_x is not None:
                    y = cur[1].copy()
                    y[cont] = cur[1][cont] + (cur[1][cont] - prev_x[cont])
                    r = evaluate(y)
                    if r is None:
                        return cur, moved
                    if r[0] < cur[0]:
                        prev_x = cur[1].copy()
                        cur = r
                        moved = True
                        continue

                cands = []
                if self._dir_mem is not None and self._dir_mem.size == c:
                    cands.append(self._dir_mem)
                eye = np.eye(c)
                for k in range(c):
                    cands.append(eye[k])
                    cands.append(-eye[k])
                for _ in range(2):
                    d = rng.normal(size=c)
                    nrm = np.linalg.norm(d)
                    if nrm > 0:
                        d = d / nrm
                        cands.append(d)
                        cands.append(-d)

                round_ok = False
                for d in cands:
                    y = cur[1].copy()
                    y[cont] += scale * d * span[cont]
                    r = evaluate(y)
                    if r is None:
                        return cur, moved
                    if r[0] < cur[0]:
                        prev_x = cur[1].copy()
                        cur = r
                        self._dir_mem = d.copy()
                        round_ok = True
                        moved = True
                        mult = 2.0
                        for _ in range(4):
                            y2 = cur[1].copy()
                            y2[cont] += mult * scale * d * span[cont]
                            r2 = evaluate(y2)
                            if r2 is None:
                                return cur, moved
                            if r2[0] < cur[0]:
                                prev_x = cur[1].copy()
                                cur = r2
                                mult *= 2.0
                            else:
                                break
                        break
                if round_ok:
                    scale = min(scale * 1.5, 0.5)
                    self._scale_mem = float(np.clip(scale, 1e-3, 0.3))
                else:
                    scale *= 0.5
                    prev_x = None
            return cur, moved

        def intensify(x0, scale):
            cur = evaluate(x0)
            if cur is None:
                return
            while not self._done:
                cur, imp = int_sweep(cur)
                if self._done:
                    return
                if imp:
                    continue
                cur, imp = pair_sweep(cur)
                if self._done:
                    return
                if imp:
                    continue
                cur, imp = pattern_search(cur, scale)
                if not imp:
                    break

        def elite_seeds(k=12):
            self._pool.sort(key=lambda t: t[0])
            seen = set()
            out = []
            for r in self._pool:
                ck = tuple(np.round(r[1], 10).tolist())
                if ck in seen:
                    continue
                seen.add(ck)
                out.append(r)
                if len(out) >= k:
                    break
            return out

        def config_bests():
            best = {}
            for r in self._pool:
                key = tuple(np.round(r[1][ints]).astype(int).tolist()) if ints.size else ()
                if key not in best or r[0] < best[key][0]:
                    best[key] = r
            return list(best.values())

        # ---------- initial stratified sample ----------
        n0 = min(max(5 * dim, 20), max(self.budget // 5, 1))
        for x in lhs_sample(n0):
            if evaluate(x) is None:
                return float(self._best_f), self._best_x

        # ---------- bandit over restart operators ----------
        ops = ["elite", "config", "incumbent", "fresh"]
        w = np.ones(len(ops))
        sig_seed = 0.2

        # ---------- main loop ----------
        while self._evals < self.budget and not self._done:
            p = 0.8 * w / w.sum() + 0.2 / len(ops)
            op = int(rng.choice(len(ops), p=p))
            before = self._best_key

            if ops[op] == "elite" and self._pool:
                top = elite_seeds(12)
                e = top[int(rng.integers(len(top)))]
                sig0 = 0.05 if rng.random() < 0.5 else 0.15
                x0 = mutate(e[1], sig0, 1.0 / dim)
            elif ops[op] == "config" and self._pool:
                cb = config_bests()
                e = cb[int(rng.integers(len(cb)))]
                x0 = mutate(e[1], 0.1, 0.0)
                sig0 = 0.1
            elif ops[op] == "incumbent" and self._best_x is not None:
                x0 = mutate(self._best_x, 0.02, 0.5)
                sig0 = 0.1
            else:
                op = ops.index("fresh")
                x0 = random_point()
                sig0 = 0.3

            sig_end = run_es(x0, sig0)
            if self._done or self._evals >= self.budget:
                break
            if self._best_x is not None:
                seed_scale = self._scale_mem
                if sig_end is not None:
                    seed_scale = float(np.clip(0.5 * (seed_scale + sig_end), 1e-3, 0.3))
                intensify(self._best_x, seed_scale)

            improved = self._best_key < before
            reward = 1.0 if improved else 0.0
            w[op] = 0.9 * w[op] + 0.1 * (0.2 + reward) * 2.0
            w = np.clip(w, 0.05, 10.0)

        return float(self._best_f), self._best_x
